import React from 'react';
import {
  AvatarIcon,
  AvatarIconSeverity,
  IconName,
} from '@metamask/design-system-react';

import { NotificationDetail } from '../notification-detail';
import { Text } from '../../component-library';
import {
  FontWeight,
  TextVariant,
  TextColor,
} from '../../../helpers/constants/design-system';

type IconProps = {
  iconName: IconName;
  severity?: AvatarIconSeverity;
};

export type NotificationDetailInfoProps = {
  icon: IconProps;
  label: string;
  detail: string;
  action?: JSX.Element;
};

/**
 * A component to display a notification detail with an icon, a label, a detail, and an action.
 *
 * @param props - The component props.
 * @param props.icon - The icon to display.
 * @param props.label - The label to display.
 * @param props.detail - The detail to display.
 * @param [props.action] - The action to display.
 * @returns The rendered component.
 */
export const NotificationDetailInfo = ({
  icon,
  label,
  detail,
  action,
}: NotificationDetailInfoProps): JSX.Element => {
  return (
    <NotificationDetail
      icon={
        <AvatarIcon
          iconName={icon.iconName}
          severity={icon.severity ?? AvatarIconSeverity.Success}
        />
      }
      primaryTextLeft={
        <Text
          variant={TextVariant.bodyLgMedium}
          fontWeight={FontWeight.Medium}
          color={TextColor.textDefault}
        >
          {label}
        </Text>
      }
      secondaryTextLeft={
        <Text
          variant={TextVariant.bodyMd}
          fontWeight={FontWeight.Normal}
          color={TextColor.textAlternative}
        >
          {detail}
        </Text>
      }
      secondaryTextRight={action}
    />
  );
};
